<template>
  <el-container>
    <el-main>
      <el-row class="head-img"></el-row>
      <el-row class="icon-list flex-wrap" type="flex" :gutter="10">
        <el-row class="logo-wrapper" type="flex" align="middle">
          <div class="logo"><img src="./images/logo.png" alt=""></div>
          <div class="info">
            <div class="user-name">店长</div>
            <div class="store-name">山东冒菜</div>
          </div>
        </el-row>
        <el-col :class="['item-wrapper', {'active':item.display}, name]" v-for="(item, name) in list" :key="name">
          <div class="item" @click="goUrl(item.url, name)">
            <div :class="['icon', name]" :style="'height:'+ iconH +'px;'" ref="iconStyle">
              <div class="order-num" v-if="item.count > 0">{{item.count}}</div>
            </div>
            <div class="name">{{item.name}}</div>
          </div>
        </el-col>
      </el-row>
      <audio src="" id="myAudio" ref="audio" loop></audio>
      <QwebBtn />
    </el-main>
  </el-container>
</template>

<script>
import audio from '../../static/new_order.mp3'
import QwebBtn from '../../components/QwebBtn/QwebBtn'
export default {
  name: 'Home',
  data () {
    return {
      list: {
        group: { name: '团购', url: '/store.php?g=Merchant&c=Store&a=group_list', count: 0 },
        scenic: { name: '景区', url: '/store.php?g=Merchant&c=Store&a=ticket_order_list', count: 0 },
        foodshop: { name: '餐饮', url: '/store.php?g=Merchant&c=Store&a=tmp_table', count: 0 },
        shop: { name: '外卖', url: '/store.php?g=Merchant&c=Store&a=shop_list', count: 0 },
        mall: { name: '商城', url: '/store.php?g=Merchant&c=Store&a=shop_list&shop_type=2', count: 0 },
        appoint: { name: '预约', url: '/store.php?g=Merchant&c=Store&a=appoint_list', count: 0 },
        store: { name: '优惠买单', url: '/store.php?g=Merchant&c=Store&a=store_order', count: 0 },
        cash: { name: '店内收银', url: '/store.php?g=Merchant&c=Store&a=store_arrival', count: 0 },
        coupon: { name: '优惠券', url: '/store.php?g=Merchant&c=Store&a=coupon_list', count: 0 },
        report: { name: '报表统计', url: '/store.php?g=Merchant&c=Store&a=report', count: 0 },
        physical_card: { name: '实体卡管理', url: '/store.php?g=Merchant&c=Store&a=physical_card', count: 0 },
        store_manage: { name: '店铺管理', url: '/store.php?g=Merchant&c=Config&a=store', count: 0 },
        sub_card: { name: '免单套餐', url: '/store.php?g=Merchant&c=Store&a=sub_card', count: 0 },
        printer: { name: '打印机参数', display: false },
        logout: { name: '退出' }
      },
      iconH: 90,
      homeInfo: {},
      storeInfo: this._util.getCache('store_staff'),
      print_mcode: '',
      print_paper: '',
      print_image: '',
      print_mkey: '',
      countArr: [],
      titleArr: [],
      nowIndex: 0,
      timeArr: {},
      playMp3Tip: null,
      newOrderTip: null,
      pack_qweb_app: window.pack_qweb_app
    }
  },
  created () {
    this.getIconHeight()
    this.getHomeInfo()
  },
  mounted () {
    if (this._util.checkAndroidApp()) {
      this.get_printer()
    }

    this.$refs.audio.src = audio
    this.isQwebApp()
  },
  methods: {

    getIconHeight () {
      let _this = this
      _this.$nextTick(function () {
        _this.iconH = _this.$refs.iconStyle[0].offsetWidth
      })
    },

    async getHomeInfo () {
      try {
        let res = await this.$api.getHome()
        if (res.errorMsg) {
          return
        }
        console.log('555555', res)
        this.homeInfo = res
        if (res.have_group != 1) {
          delete this.list.group
        } else {
          this.list.group.name = res.have_group_name
          this.countArr.push('group')
          this.titleArr.push(res.have_group_name)
        }

        if (res.have_scenic != 1) {
          delete this.list.scenic
        } else {
          this.list.scenic.name = res.have_scenic_name
          this.countArr.push('scenic')
          this.titleArr.push(res.have_scenic_name)
        }

        if (res.have_meal != 1) {
          delete this.list.foodshop
        } else {
          this.list.foodshop.name = res.have_meal_name
          this.countArr.push('foodshop')
          this.titleArr.push(res.have_meal_name)
        }

        if (res.have_shop != 1) {
          delete this.list.shop
        } else {
          this.list.shop.name = res.have_shop_name
          this.countArr.push('shop')
          this.titleArr.push(res.have_shop_name)
        }

        if (res.have_mall != 1) {
          delete this.list.mall
        } else {
          this.list.mall.name = res.have_mall_name
          this.countArr.push('mall')
          this.titleArr.push(res.have_mall_name)
        }

        if (res.have_appoint != 1) {
          delete this.list.appoint
        } else {
          this.list.appoint.name = res.have_appoint_name
          this.countArr.push('appoint')
          this.titleArr.push(res.have_appoint_name)
        }

        if (res.have_store != 1) {
          delete this.list.store
        } else if (res.have_store_name != '') {
          this.list.store.name = res.have_store_name
        }

        if (res.pay_in_store != 1) {
          delete this.list.cash
        } else {
          this.list.cash.name = res.have_cash_name
          this.countArr.push('cash')
          this.titleArr.push(res.have_cash_name)
        }

        if (res.open_sub_card != 1) {
          delete this.list.sub_card
        }

        this.checkPrint()
      } catch (e) {
        console.log('请求首页数据错误', e)
      }
    },

    goUrl (url, name) {
      console.log('5555ddd', process.env.VUE_APP_BASE_API + url + '&web_session=' + this.storeInfo.web_session)

      // 退出按钮
      if (name == 'logout') {
        this.$confirm('您确定要退出吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          this._util.removeCache('store_staff')
          this._util.removeCache('ticket')
          this._util.removeCache('store_config')
          this.$router.replace({ path: '/login' })
        }).catch(() => {
          console.log('已取消退出')
        })
        return
      }

      // 打印机参数按钮
      if (name == 'printer') {
        var content = '<div style="letter-spacing:2px;font-size:16px;">'
        content += '<div>终&nbsp;端&nbsp;号：' + this.print_mcode + '</div>'
        content += '<div>密&nbsp;&nbsp;&nbsp;&nbsp;钥：' + this.print_mkey + '</div>'
        content += '<div>纸张类型：' + this.print_paper + 'mm</div>'
        content += '<div>支持图片：' + (this.print_image == '1' ? '支持' : '不支持') + '</div>'
        content += '<div>&nbsp;</div>'
        content += '<div style="font-size:12px;">' + '添加打印机后，请重新启动本软件。' + '</div>'
        content += '</div>'

        this.$alert(content, '打印机参数', {
          dangerouslyUseHTMLString: true
        })

        return
      }

      if (url) {
        this._util.setCache('home_type', 'newHome')
        url = process.env.VUE_APP_BASE_API + url + '&web_session=' + this.storeInfo.web_session
        if (this.list[name].count > 0) {
          var nowType = name
          if (this.timeArr[nowType]) {
            delete this.timeArr[nowType]
          }
        }
        if (this._util.checkApp()) {
          if (this._util.checkAndroidApp()) {
            window.pigcmspackapp.createwebview(url)
          } else {
            var iosHref = window.btoa(url)
            iosHref = iosHref.replace('/', '&')
            this._util.iosFunction('createwebview/' + iosHref, { name: 'createwebview', url: iosHref })
          }
        } else {
          window.location.href = url
        }
      }
    },

    // 获取打印机信息
    async get_printer (arg1, arg2, arg3) {
      if (arg1 == '') {
        return
      }
      $('.printer').show()
      this.list.printer.display = true
      this.print_mcode = arg1
      this.print_paper = arg2
      this.print_image = arg3
      this.print_mkey = this._util.getDeviceId()
      let hasPrint = await this.$api.checkPrint({ mkey: this.print_mkey })
      if (hasPrint.status && hasPrint.status == 1) {
        setInterval(async function () {
          let printWorkData = await this.$api.getPrint({ mkey: this.print_mkey })
          if (printWorkData.status && printWorkData.status == 1 && printWorkData.info != '') {
            window.pigcmspackapp.printer_work(printWorkData.info, '')
          }
        }, 3000)
      }
    },

    checkPrint () {
      var mp3 = this.$refs.audio.src
      var _this = this
      setInterval(async function () {
        var nowType = _this.countArr[_this.nowIndex]
        let typeData = await _this.$api.getPrinterType({ time: _this.timeArr[nowType], nowType: nowType })
        _this.timeArr[nowType] = typeData.time
        _this.list[nowType].count = typeData.count

        if (typeData.count > 0) {
          if (_this.newOrderTip != null) {
            _this.newOrderTip.close()
          }

          if (_this.pack_qweb_app) {
            _this._qweb.max_window()
          }

          if (_this.playMp3Tip == null) {
            if (_this.pack_qweb_app) {
              _this._qweb.play_mp3(mp3, 'new_order', 1000)
            } else if (_this._util.checkAndroidApp()) {
              window.pigcmspackapp.voicetip(mp3, 1000)
            } else {
              _this.$refs.audio.play()
            }
          }
          var tipTitle = '您有新的' + _this.titleArr[_this.nowIndex] + '订单需要处理'
          /* {pigcms{:L_("音乐播放5分钟")} */
          _this.playMp3Tip = setTimeout(function () {
            if (_this._qweb.pack_qweb_app) {
              _this._qweb.stop_mp3()
            } else if (_this._util.checkAndroidApp()) {
              window.pigcmspackapp.voicetip_stop()
            } else {
              _this.$refs.audio.pause()
            }
          }, 300000)

          _this.newOrderTip = _this.$notify.info({
            title: '新订单提示',
            message: tipTitle,
            onClose: () => {
              if (_this.pack_qweb_app) {
                _this._qweb.stop_mp3()
              } else if (_this._util.checkAndroidApp()) {
                window.pigcmspackapp.voicetip_stop()
              } else {
                _this.$refs.audio.pause()
              }
              clearTimeout(_this.playMp3Tip)
              _this.playMp3Tip = null
              _this.newOrderTip = null
            }
          })
        }
        if (_this.nowIndex + 1 == _this.countArr.length) {
          _this.nowIndex = 0
        } else {
          _this.nowIndex++
        }
      }, 5000)
    },

    // "判断在pc打包软件中打开")}
    isQwebApp () {
      var _this = this
      if (this.pack_qweb_app) {
        this._qweb.stop_mp3()
        this._qweb.change_window('0', '0')

        this._qweb.check_soft('print_soft.exe', 'no_tip', 1, '')
        setInterval(function () {
          _this._qweb.check_soft('print_soft.exe', 'no_tip', 1, '')
        }, 3000)
      }
    }
  },

  components: {
    QwebBtn
  }
}
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
  .el-container
    height 100%
    .el-main
      padding 0
      overflow-x hidden
      .head-img
        background url(./images/bg.png) no-repeat
        background-size 100% 100%
        height 30%
      .icon-list
        padding 120px 8% 0 8%
        box-sizing border-box
        position relative
        max-width 1800px
        margin 0 auto !important
        &:last-child
          margin-bottom 0
        .item-wrapper
          border-radius 4px
          margin-bottom 120px
          width 14%
          font-size 22px
          @media screen and (max-width: 1280px)
            font-size 20px
            margin-bottom 80px
          @media screen and (max-width: 1097px)
            width 20%
            font-size 18px
          @media screen and (max-width: 800px)
            width 25%
            font-size 16px
          @media screen and (max-width: 600px)
            width 33.33%
            font-size 16px
          .item
            cursor pointer
            .icon
              background-image url("")
              background-repeat no-repeat
              background-size 100%
              width 100%
              max-width 90px
              margin 0 auto
              position relative
              &.group
                background-image url(./images/group_hover.png)
              &.scenic
                background-image url(./images/scenic_hover.png)
              &.foodshop
                background-image url(./images/meal_hover.png)
              &.shop
                background-image url(./images/shop_hover.png)
              &.mall
                background-image url(./images/mall_hover.png)
              &.appoint
                background-image url(./images/appoint_hover.png)
              &.store
                background-image url(./images/store_hover.png)
              &.cash
                background-image url(./images/arrival_hover.png)
              &.coupon
                background-image url(./images/coupon_hover.png)
              &.report
                background-image url(./images/report_hover.png)
              &.physical_card
                background-image url(./images/physical_card_hover.png)
              &.store_manage
                background-image url(./images/store_manage_hover.png)
              &.sub_card
                background-image url(./images/sub_card_hover.png)
              &.printer
                background-image url(./images/printer_hover.png)
              &.logout
                background-image url(./images/logout_hover.png)
              .order-num
                position absolute
                top 0
                right 0
                width 30px
                height 30px
                border-radius 50%
                background red
                text-align center
                line-height 30px
                color #fff
                font-weight bold
                box-shadow 0 2px 4px rgba(0, 0, 0, .3)
                font-size 14px
            .name
              margin-top 20px
              text-align center
              color #333
        .item-wrapper.printer
          display none
        .item-wrapper.printer.active
          display block
        .logo-wrapper
          position absolute
          top -65px
          left 9%
          .logo
            box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.3)
            border-radius 50%
            margin-right 20px
            width 130px;
            height 130px;
            overflow hidden
            img
              vertical-align top
              width 100%
          .info
            .user-name
              font-size 20px
              color #393939
              margin-bottom 30px
            .store-name
              font-size 14px
              color #999
      .audio-wrapper
        display block

</style>
