<template>
    <div class="btn-wrapper" v-if="isShow">
      <span class="icon scale" @click="minWindow">－</span>
      <span class="icon close" @click="closeWindow">×</span>
    </div>
</template>

<script>
export default {
  name: 'QwebBtn',
  data () {
    return {
      isShow: window.pack_qweb_app
    }
  },
  methods: {
    minWindow () {
      this._qweb.min_window()
    },

    closeWindow () {
      this.$confirm('您确定要关闭软件吗？', '确认提醒', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        center: true
      }).then(() => {
        this._qweb.close_window()
      }).catch(() => {
        console.log('取消关闭软件')
      })
    }
  }
}
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
  .btn-wrapper
    position fixed
    top 0
    right 0
    padding 10px 10px 15px 15px
    border-radius 0 0 0 15px
    background rgba(255, 255, 255, .6)
    .icon
      width 30px
      height 30px
      text-align center
      line-height 30px
      font-size 28px
      border-radius 50%
      color #fff
      display inline-block
      box-shadow 0 2px 4px rgba(0, 0, 0, .3)
      &.scale
        background #51bbaf
        margin-right 20px
      &.close
        background #e8575a
</style>
